<?php require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/layout.php';$q=db()->prepare('SELECT * FROM upload_albums WHERE slug=?');$q->execute([$_GET['slug']??'']);$album=$q->fetch();if(!$album){http_response_code(404);require_once __DIR__.'/includes/not-found.php';render_image_not_found();}$q=db()->prepare('SELECT i.* FROM images i JOIN upload_album_images ai ON ai.image_id=i.id WHERE ai.album_id=? AND i.status="ready" ORDER BY ai.sort_order,i.id');$q->execute([$album['id']]);$items=$q->fetchAll();$description=t('seo_collection_description',['count'=>count($items)]);page_start(t('multi_album_title'),$description,['index'=>false,'canonical_path'=>'/c/'.$album['slug']]);?><main class="album-public"><section class="album-public-head"><div><p class="eyebrow"><?=e(t('multi_album_label'))?></p><h1><?=e(t('multi_album_title'))?></h1><p><?=count($items)?> <?=e(t('images'))?> · <?=e($album['created_at'])?></p></div><button class="button button-secondary" type="button" id="copyAlbum"><?=e(t('share_album'))?></button></section><?php if(!$items):?><div class="empty"><p><?=e(t('empty_album'))?></p></div><?php else:?><div class="album-public-grid"><?php foreach($items as $image):?><article><a href="/<?=e($image['short_id'])?>"><img src="/<?=e($image['short_id'])?>.<?=e($image['extension'])?>" alt="<?=e($image['original_filename'])?>" loading="lazy"></a><div><b><?=e($image['original_filename'])?></b><small><?=e(format_bytes((int)$image['size']))?> · <?=number_format((int)$image['views'])?> <?=e(t('views'))?></small></div></article><?php endforeach?></div><?php endif?></main><script>document.getElementById('copyAlbum')?.addEventListener('click',async()=>{await navigator.clipboard.writeText(location.href);toast(<?=json_encode(t('copied'),JSON_UNESCAPED_UNICODE)?>)});</script><?php page_end();
